import Database from "better-sqlite3";
import { sen } from "@brokely/domain";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { generateSQLiteDrizzleJson, generateSQLiteMigration } from "drizzle-kit/api";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { listCategories, quickStart, recordPurchase, seedDefaultCategories } from "./repositories";
import * as schema from "./schema";
import { NOW, testId } from "./test-db";

/**
 * The phone runs the SQL files in ./drizzle (generated by `pnpm --filter @brokely/local-db
 * db:generate`), not schema.ts. These tests keep the two in step.
 */
const dir = join(import.meta.dirname, "..", "drizzle");

function journal(): { entries: { idx: number; tag: string }[] } {
  return JSON.parse(readFileSync(join(dir, "meta", "_journal.json"), "utf8"));
}

describe("phone migrations", () => {
  it("are up to date with schema.ts (run db:generate after changing the schema)", async () => {
    const snapshots = readdirSync(join(dir, "meta")).filter((f) => f.endsWith("_snapshot.json"));
    const latest = JSON.parse(readFileSync(join(dir, "meta", snapshots.sort().at(-1)!), "utf8"));

    const pending = await generateSQLiteMigration(latest, await generateSQLiteDrizzleJson(schema));

    expect(pending).toEqual([]);
  });

  it("build a working database from nothing, in journal order (FR-SYNC-02)", () => {
    const sqlite = new Database(":memory:");
    sqlite.pragma("foreign_keys = ON");
    for (const { tag } of journal().entries) {
      const sql = readFileSync(join(dir, `${tag}.sql`), "utf8");
      for (const statement of sql.split("--> statement-breakpoint")) sqlite.exec(statement);
    }

    let n = 1000;
    const ctx = { db: drizzle(sqlite, { schema }), newId: () => testId(n++), now: () => NOW };
    seedDefaultCategories(ctx);
    quickStart(ctx, {
      budgetSen: sen(40000),
      startDate: "2026-11-01",
      endDateInclusive: "2026-11-30",
    });
    const laundry = listCategories(ctx.db).find((c) => c.name === "Laundry")!.id;
    const saved = recordPurchase(ctx, {
      amountSen: sen(500),
      categoryId: laundry,
      localDate: "2026-11-02",
      occurredAt: NOW,
    });

    expect(saved.ok).toBe(true);
  });
});
